// Read-only independent host reconciliation, including missing-receipt crash attempts.
using System;using System.IO;using System.Diagnostics;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Web.Script.Serialization;using Microsoft.Win32;
internal static class InspectMatrixCleanupPostSingle {
    static readonly JavaScriptSerializer Json=new JavaScriptSerializer(){MaxJsonLength=64*1024*1024};
    static Dictionary<int,Process> Live;static List<object> Pids=new List<object>();static List<string> Problems=new List<string>();static HashSet<string> Seen=new HashSet<string>();
    static readonly Dictionary<string,DateTime> PriorAbsent=new Dictionary<string,DateTime>();
    const string PriorHash="6b4eed2f93ac0e9ce2e052aff6f22c9b742ef6232338f684c2329da54fb911cd";
    static string Evidence;
    static void LoadPrior(){byte[] bytes=File.ReadAllBytes(Path.Combine(Evidence,"cleanup-checkpoint-0001.json"));using(var sha=System.Security.Cryptography.SHA256.Create())if(BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant()!=PriorHash)throw new Exception("PRIOR_CLEANUP_RAW_HASH_DRIFT");var root=Json.Deserialize<Dictionary<string,object>>(System.Text.Encoding.UTF8.GetString(bytes).TrimStart('\uFEFF'));if(Convert.ToInt32(root["inner_exit_code"])!=0)throw new Exception("PRIOR_CLEANUP_NOT_PASS");foreach(Dictionary<string,object> attempt in (ArrayList)root["attempts"]){string nonce=Convert.ToString(attempt["attempt"]);DateTime observed=DateTime.Parse(Convert.ToString(attempt["observed_utc"])).ToUniversalTime();foreach(Dictionary<string,object> p in (ArrayList)attempt["processes"])if(!Convert.ToBoolean(p["present"])&&Convert.ToBoolean(p["query_succeeded"]))PriorAbsent[nonce+":"+p["pid"]]=observed;}}
    static void CheckPid(string source,int pid,long? created,DateTime observed){if(pid<=0)return;string key=source+":"+pid+":"+created;if(!Seen.Add(key))return;bool? present=false;bool reused=false;object current=null,prior=null;string error=null;try{Process p;if(Live.TryGetValue(pid,out p)&&!p.HasExited){long birth=p.StartTime.ToUniversalTime().ToFileTimeUtc();reused=created.HasValue?created.Value!=birth:DateTime.FromFileTimeUtc(birth)>observed;present=!reused;string image=null,imageError=null;try{image=p.MainModule.FileName;}catch(Exception e){imageError=e.GetType().Name+":"+e.Message;}current=new{created_filetime=birth,image=image,image_query_error=imageError};if(present==true)Problems.Add("RECORDED_PID_STILL_PRESENT:"+pid+":"+source);}}catch(Exception e){error=e.GetType().Name+":"+e.Message;present=null;string[] parts=source.Split(Path.DirectorySeparatorChar);DateTime priorUtc;string nonce=parts.FirstOrDefault(part=>part.Length==32&&part.All(c=>"0123456789abcdef".Contains(c)));if(nonce!=null&&PriorAbsent.TryGetValue(nonce+":"+pid,out priorUtc)&&priorUtc>observed){present=false;reused=true;prior=new{source="cleanup-checkpoint-0001.json",raw_sha256=PriorHash,observed_absent_utc=priorUtc.ToString("o"),inference="Original PID identity already independently absent after this event; present inaccessible PID cannot resurrect that ended process. Current creation identity is unknown."};}else Problems.Add("RECORDED_PID_QUERY_UNKNOWN:"+pid+":"+source);}Pids.Add(new{source=source,pid=pid,recorded_created_filetime=created,recorded_utc=observed.ToString("o"),present=present,pid_reused=reused,current_identity=current,error=error,prior_absence_proof=prior});}
    static void Walk(object value,string source,DateTime inherited){var d=value as Dictionary<string,object>;if(d!=null){DateTime observed=inherited;object stamp;if(d.TryGetValue("utc",out stamp)){DateTime parsed;if(DateTime.TryParse(Convert.ToString(stamp),out parsed))observed=parsed.ToUniversalTime();}foreach(string key in new[]{"pid","daemon_pid","broker_pid","launcher_pid","new_daemon_pid","parent_pid"}){object id;if(!d.TryGetValue(key,out id))continue;string birth=key=="pid"?"created_filetime":key.Replace("_pid","_created_filetime");object raw;long? created=d.TryGetValue(birth,out raw)?(long?)Convert.ToInt64(raw):null;CheckPid(source,Convert.ToInt32(id),created,observed);}foreach(var pair in d)Walk(pair.Value,source,observed);}else{var a=value as object[];if(a!=null)foreach(var item in a)Walk(item,source,inherited);else{var list=value as ArrayList;if(list!=null)foreach(var item in list)Walk(item,source,inherited);}}}
    internal static int Main(string[] args){if(args.Length!=2)return 64;string evidence=Path.GetFullPath(args[0]),output=Path.GetFullPath(args[1]);if(!output.StartsWith(evidence+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||File.Exists(output))return 65;Live=Process.GetProcesses().ToDictionary(p=>p.Id);var unknown=new List<int>();var matching=new List<object>();string scope=Path.GetFullPath(".tmp/verification-lpac")+Path.DirectorySeparatorChar;string hostScope=Path.GetFullPath(".tmp/verification-lpac-single-host")+Path.DirectorySeparatorChar;foreach(var p in Live.Values){try{string image=p.MainModule.FileName;if((image.StartsWith(scope,StringComparison.OrdinalIgnoreCase)||image.StartsWith(hostScope,StringComparison.OrdinalIgnoreCase))){matching.Add(new{pid=p.Id,image=image});Problems.Add("SCOPE_IMAGE_PRESENT:"+p.Id);}}catch{unknown.Add(p.Id);}}
        Evidence=evidence;LoadPrior();var attempts=new SortedSet<string>();foreach(string kind in new[]{"attempts","node-file-attempts","crash-attempts","daemon-attempts","single-process-host-controls","host-wmi-attempts"}){string parent=Path.Combine(evidence,kind);if(!Directory.Exists(parent))continue;foreach(string directory in Directory.GetDirectories(parent)){string nonce=Path.GetFileName(directory);Guid parsed;if(!Guid.TryParseExact(nonce,"N",out parsed))throw new Exception("NONCE");attempts.Add(nonce);foreach(string file in Directory.GetFiles(directory,"*.json",SearchOption.AllDirectories)){if(Path.GetFileName(file)=="identity.json"||Path.GetFileName(file)=="members.json")continue;Walk(Json.DeserializeObject(File.ReadAllText(file)),file,File.GetLastWriteTimeUtc(file));}foreach(string file in Directory.GetFiles(directory,"events.jsonl",SearchOption.AllDirectories))foreach(string line in File.ReadLines(file)){var row=Json.Deserialize<Dictionary<string,object>>(line);Walk(row,file,DateTime.Parse(Convert.ToString(row["utc"])).ToUniversalTime());}}}
        var resources=new List<object>();foreach(string nonce in attempts){string moniker="specforge.regread."+nonce,profile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Packages",moniker),storage="Software\\Classes\\Local Settings\\Software\\Microsoft\\Windows\\CurrentVersion\\AppContainer\\Storage\\"+moniker;bool profilePresent=Directory.Exists(profile),storagePresent,canaryPresent;using(var key=Registry.CurrentUser.OpenSubKey(storage,false))storagePresent=key!=null;using(var key=Registry.CurrentUser.OpenSubKey("Software\\SpecForgeIsolationCanary-"+nonce,false))canaryPresent=key!=null;if(profilePresent||storagePresent||canaryPresent)Problems.Add("OWNED_RESOURCE_PRESENT:"+nonce);resources.Add(new{attempt=nonce,profile_present=profilePresent,private_storage_present=storagePresent,canary_key_present=canaryPresent});}
        var result=new{utc=DateTime.UtcNow.ToString("o"),method="Independent current host PID/birth reconciliation from all archived events and crash/daemon records; exact owned registry/profile paths; no process termination or resource deletion",attempts=resources.ToArray(),processes=Pids.ToArray(),matching_synthetic_images=matching.ToArray(),unreadable_unrelated_image_pids=unknown.ToArray(),problems=Problems.ToArray(),limits="Unreadable unrelated processes are not claimed absent. Historical unknown exit codes remain unknown. This is cleanup verification, never application success.",inner_exit_code=Problems.Count==0?0:1};using(var file=new FileStream(output,FileMode.CreateNew,FileAccess.Write))using(var writer=new StreamWriter(file,new System.Text.UTF8Encoding(false)))writer.WriteLine(Json.Serialize(result));Console.WriteLine("MATRIX_CLEANUP attempts="+attempts.Count+" pid_observations="+Pids.Count+" problems="+Problems.Count+" EXIT="+(Problems.Count==0?0:1));foreach(string problem in Problems)Console.WriteLine(problem);return Problems.Count==0?0:1;
    }
}
